// EXACT match, never a prefix: /shop has the tab bar while /shop/:id does not,
// and /wallet has it while /wallet/withdraw does not — a prefix test would put
// the bar back on exactly the screens the design removed it from.
export function hasChrome(routes: readonly string[], pathname: string): boolean {
  const p = pathname.length > 1 ? pathname.replace(/\/+$/, '') : pathname;
  return routes.includes(p);
}
